('d7ead057-1b7f-4235-ab9e-a773333756fb', '21feff02-016d-46e2-bb9d-c27495133b1b', '62. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek II.', 'Tengelyesen szimmetrikus négyszögek (téglalap, négyzet, rombusz, deltoid, szimmetrikus trapéz) szimmetriatengelyei.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "16788c9f-2239-4a17-9f52-80bef427243d", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "4248d65a-12f9-4dd4-933b-8e667b2a4ba1", "text": "Hány szimmetriatengelye van a téglalapnak (ami nem négyzet)? (az oldalfelező merőlegesek)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "c27e0f45-8fcd-42f2-913f-27d588c04b60", "text": "Hány szimmetriatengelye van a rombusznak (ami nem négyzet)? (az átlók egyenesei)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "f554f160-8f91-41b8-8d0a-2390cb7447a0", "text": "Hány szimmetriatengelye van a deltoidnak (ha nem rombusz)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "bf0e2879-d4aa-41eb-9c4b-c9a152bfb9c2", "text": "A szimmetrikus (egyenlő szárú) trapéznak 1 szimmetriatengelye van.", "type": "true-false", "options": [{"id": "cc532af2-9a44-4f92-aab5-548e467c8352", "text": "Igaz", "isCorrect": true}, {"id": "ce83d517-2cba-4879-88ae-43ebdbffeb6e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b4fa1bfd-f33b-471f-b534-bf245ebae973", "text": "Az általános paralelogrammának (ami nem rombusz és nem téglalap) NINCS tengelyes szimmetriatengelye.", "type": "true-false", "options": [{"id": "0a5bd549-6658-41c9-985f-bc61d6220383", "text": "Igaz (középpontosan szimmetrikus, de tengelyesen nem)", "isCorrect": true}, {"id": "83397df7-91fc-43e1-90bf-fc9b84db280d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c96e8400-63c1-49e7-ae83-5c4c4d36493c", "text": "Hány szimmetriatengelye van a szabályos ötszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW()),
('66d9b845-6e95-4874-9804-aa0d5af45a10', '21feff02-016d-46e2-bb9d-c27495133b1b', '63. óra: Szerkesztési feladatok', 'Szakasz- és szögmásolás, szögfelezés, háromszögszerkesztések gyakorlása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "3b4f9796-76be-42dc-94dc-e48111316ed7", "text": "Hogyan felezünk meg egy 80°-os szöget szerkesztéssel?", "type": "multiple-choice", "options": [{"id": "b9b1206f-15b2-4586-b0c9-7822644a6006", "text": "Megszerkesztjük a szög szögfelező egyenesét, így két 40°-os szöget kapunk", "isCorrect": true}, {"id": "adb02f17-bd9a-4d8f-821b-9fbd9e7aca8f", "text": "Levágunk belőle 10 fokot", "isCorrect": false}, {"id": "6b2e8560-1cf7-4db4-9571-6c951bb6c66c", "text": "Merőlegest húzunk a szög egyik szárára", "isCorrect": false}, {"id": "528629dc-0539-4f83-9596-bffebfe7edde", "text": "Szögmérővel elosztjuk", "isCorrect": false}], "timeLimit": 15}, {"id": "93acf596-9b10-4b3a-828d-6508c88569c4", "text": "A szögfelezéshez körzőt és egyenes vonalzót használsz.", "type": "true-false", "options": [{"id": "46aa5624-e201-4e87-8458-8fef4973028a", "text": "Igaz", "isCorrect": true}, {"id": "a94965a2-2542-4618-bdef-7b14a0e829ae", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "689bd4ac-b649-4a4a-a516-21027690a05f", "text": "Hány fokos szögeket kapunk egy 90°-os derékszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "863231d3-f875-4768-9ca8-d27125e6b238", "text": "Hány fokos szögeket kapunk egy 180°-os egyenesszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "8d3740d5-d8ac-4834-8a15-68b6c1bc2341", "text": "Szerkeszthető-e 60°-os szög kizárólag körzővel és vonalzóval (szabályos háromszög szerkesztésével)?", "type": "true-false", "options": [{"id": "ca5565bb-a88a-4277-9df1-a2ffd22ebc92", "text": "Igaz", "isCorrect": true}, {"id": "f733beb7-22c7-4316-9ad1-5f290f20eb29", "text": "Hamis", "isCorrect": false}], "timeLim