('b39eac53-703c-4c14-8a5e-fa25bff78cdd', '21feff02-016d-46e2-bb9d-c27495133b1b', '66. óra: Témazáró dolgozat', 'Témazáró számonkérés a Geometria és tengelyes tükrözés fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "486f3866-08d1-4e6d-bcc9-72c828dddfe8", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "cccdf64f-3b70-44ea-a432-fdddbc65da07", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "e9a5851a-3163-4e7c-9b8e-5bc5f6098da6", "text": "3. Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "bb599870-d538-427d-aa98-1eb7acbd52ca", "text": "4. Hány szimmetriatengelye van az egyenlő szárú (nem szabályos) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "d5f9a536-8d4d-4800-8d35-1da46bd93568", "text": "5. Ha a kör sugara 4,5 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "dd6128e2-3d94-42e3-a16a-10f3d49abadc", "text": "6. A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "cc584529-ae9b-4ace-a450-3d3f14c88211", "text": "Igaz", "isCorrect": true}, {"id": "9cfaed5d-5c35-4c27-b532-ef4eb506a369", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e0c0f2db-e72b-4854-8bba-a0cfd588c178", "text": "7. Szerkeszthető-e háromszög 3 cm, 5 cm, 9 cm oldalakkal?", "type": "true-false", "options": [{"id": "04ed9e83-8d4a-48e0-91e6-fc14383efca1", "text": "Igaz", "isCorrect": false}, {"id": "42cdbe5a-5340-43e8-91da-07b2311d84a0", "text": "Hamis (3+5 < 9)", "isCorrect": true}], "timeLimit": 15}, {"id": "ed6abafb-2460-4729-9563-5cdc54170cbe", "text": "8. Hány fokos szögeket kapunk egy 120°-os szög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "bc959e52-12b1-4c2f-b2f1-8fd3f101fe6d", "text": "9. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "d8a789bd-2053-4f85-850d-badc9f9dd08e", "text": "Igaz", "isCorrect": true}, {"id": "e2e4e3b8-5d4b-40da-aedc-86695e1e7b43", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9b54db51-2298-4f85-b6d7-66a28e935f2d", "text": "10. Hol található a tükörtengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "96ef33a6-e27e-4746-9b7a-74d94352e51b", "text": "Önmagában", "isCorrect": true}, {"id": "b1e34291-ad14-4f3c-adb4-563469739f5b", "text": "Az origóban", "isCorrect": false}, {"id": "3caa67d5-69cf-41ab-bb0b-67769832da6b", "text": "A tengely végétől 5 cm-re", "isCorrect": false}, {"id": "f8414852-e6ac-4884-bfee-a83b563b1170", "text": "A sík szélén", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());